/* Own minimal simulator of the Wix cookie banner for integration tests (no vendor code). Mimics public identifiers
   only: window.consentPolicyManager.getCurrentConsentPolicy(), the data-hook attributes and roles of the banner and of
   its settings layer, and the cookie "consent-policy". The settings layer follows the markup captured from the vendor
   (test/fixtures/cmp/wix/settings-layer.html), which test/integration/cmp/adapters/wix-captured-markup.test.ts compares
   it with.
   The script tag's data-sim-variant says what the first layer offers: "Alle ablehnen" (decline), only
   "Cookie-Einstellungen" and "Zustimmen" (no-decline), "Zustimmen" and the close button alone (close-only), or
   "Zustimmen" and × with the settings control outside the banner (settings-outside). data-sim-policy="throws" makes
   getCurrentConsentPolicy() throw, as a platform whose policy cannot be read.
   The settings control opens the settings layer as a dialog of its own; the first layer stays open behind it. As the
   vendor's, the layer's container covers the viewport at once, while its panel stays transparent for a moment and
   only then fades in. The layer holds a close control without a hook, one section per category (essential, marketing, functional, analytics),
   each with a shown toggle around a visually hidden checkbox, the essential one on and disabled, and "Auswahl
   bestätigen", which stores the switches as they are and closes both layers. data-sim-settings says how the layer
   differs: "preselected" (analytics on), "two-saves" (a second save control), "unsaved" (saving closes both layers
   without storing an answer), "hidden-copy" (analytics on, behind a hidden copy of the layer with every switch off that
   comes first in the page), "locked-on" (analytics on and disabled like the essential switch).
   Opening the layer loads its stylesheet; accepting or saving a category loads the local fake tracker. */
(function () {
  var script = document.currentScript;
  var variant = (script && script.getAttribute('data-sim-variant')) || 'decline';
  var settingsVariant = (script && script.getAttribute('data-sim-settings')) || 'off';
  var policyFails = !!script && script.getAttribute('data-sim-policy') === 'throws';
  var NAMES = { functional: 'func', analytics: 'anl', advertising: 'adv' };
  var BASE = 'https://static.parastorage.com/services/cookie-consent-banner-for-uou/1.0.0/';

  function readStored() {
    var parts = document.cookie.split(';');
    for (var i = 0; i < parts.length; i++) {
      var p = parts[i].trim();
      if (p.indexOf('consent-policy=') !== 0) continue;
      try { return JSON.parse(decodeURIComponent(p.slice('consent-policy='.length))); } catch (e) { return null; }
    }
    return null;
  }
  var stored = readStored();

  // As on Wix, dataToThirdParty is on before any answer and after either one: the banner does not ask for it.
  function policyOf(s) {
    var policy = { essential: true, dataToThirdParty: !s || s.dt3 === 1 };
    for (var k in NAMES) policy[k] = !!(s && s[NAMES[k]] === 1);
    return policy;
  }
  window.consentPolicyManager = {
    getCurrentConsentPolicy: function () {
      if (policyFails) throw new Error('consent policy unavailable');
      return { defaultPolicy: !stored, policy: policyOf(stored) };
    }
  };

  function loadTracker() {
    var s = document.createElement('script');
    s.src = 'https://stats.wix.test/t.js';
    document.head.appendChild(s);
  }
  function store(choice) {
    stored = { ess: 1, func: choice.func, anl: choice.anl, adv: choice.adv, dt3: 1, ts: Date.now() };
    document.cookie = 'consent-policy=' + encodeURIComponent(JSON.stringify(stored)) + '; path=/; max-age=15552000; SameSite=Lax';
    if (choice.func || choice.anl || choice.adv) loadTracker();
  }
  function save(all) {
    var v = all ? 1 : 0;
    store({ func: v, anl: v, adv: v });
  }

  var btn = 'margin:4px;padding:10px 16px;border:1px solid #116dff;font:14px sans-serif;cursor:pointer;';

  // Category keys of the stored answer in the order the layer lists them; the essential one cannot be switched off.
  var CATEGORIES = [
    ['ess', 'Erforderliche Cookies', 'Für den Betrieb der Website nötig.'],
    ['adv', 'Marketing-Cookies', 'Für Werbung und deren Messung.'],
    ['func', 'Funktionale Cookies', 'Für zusätzliche Funktionen.'],
    ['anl', 'Analyse-Cookies', 'Für Statistiken zur Nutzung.']
  ];
  var HIDDEN_INPUT = 'position:absolute;width:0;height:0;margin:0;opacity:0';
  // How long the panel stays transparent after the click, and how long it then takes to fade in.
  var PANEL_DELAY_MS = 900;
  var PANEL_FADE_MS = 600;

  function openSettings(root) {
    var css = document.createElement('link');
    css.rel = 'stylesheet';
    css.href = BASE + 'settings.css';
    document.head.appendChild(css);
    if (settingsVariant === 'hidden-copy') document.body.appendChild(settingsLayer(false, true).el);
    var preselected = settingsVariant === 'preselected' || settingsVariant === 'hidden-copy';
    var layer = settingsLayer(preselected, false);
    document.body.appendChild(layer.el);
    setTimeout(function () {
      layer.panel.style.transition = 'opacity ' + PANEL_FADE_MS + 'ms, transform ' + PANEL_FADE_MS + 'ms';
      layer.panel.style.opacity = '1';
      layer.panel.style.transform = 'translate(-50%,-50%)';
    }, PANEL_DELAY_MS);

    var saves = layer.el.querySelectorAll('[data-hook="consent-banner-settings-save-button"]');
    for (var j = 0; j < saves.length; j++) {
      saves[j].addEventListener('click', function () {
        var on = function (key) { return layer.inputs[key].checked ? 1 : 0; };
        if (settingsVariant !== 'unsaved') store({ func: on('func'), anl: on('anl'), adv: on('adv') });
        layer.el.remove();
        if (root) root.remove();
      });
    }
  }

  // The layer as the vendor renders it. The switch states are set as properties, not attributes, as a rendering
  // framework sets them.
  function settingsLayer(analyticsOn, hidden) {
    var el = document.createElement('div');
    el.setAttribute('data-hook', 'consent-banner-settings-container');
    el.setAttribute('role', 'dialog');
    el.style.cssText = 'position:fixed;inset:0;z-index:100000;background:rgba(0,0,0,.4);color:#222;font:14px/1.4 sans-serif' +
      (hidden ? ';visibility:hidden' : '');
    var dialog = document.createElement('section');
    dialog.setAttribute('data-hook', 'consent-banner-settings-dialog');
    // A hidden copy is never faded in; the shown layer's panel starts transparent and a little lower.
    dialog.style.cssText = 'position:absolute;top:50%;left:50%;box-sizing:border-box;width:560px;max-height:90vh;overflow:auto;padding:16px 24px;background:#fff;box-shadow:0 2px 16px rgba(0,0,0,.3)' +
      (hidden ? ';transform:translate(-50%,-50%)' : ';opacity:0;transform:translate(-50%,-40%)');
    dialog.innerHTML =
      '<h2 style="margin:0 0 8px;font-size:18px">Erweiterte Cookie-Einstellungen</h2>' +
      '<button aria-label="Einstellungen schließen" style="position:absolute;right:8px;top:8px;padding:4px 8px;border:0;background:none;font:inherit;cursor:pointer">×</button>';
    var close = dialog.querySelector('button');
    close.addEventListener('click', function () { el.remove(); });

    var inputs = {};
    for (var i = 0; i < CATEGORIES.length; i++) {
      var key = CATEGORIES[i][0];
      var lockedOn = key === 'ess' || (settingsVariant === 'locked-on' && key === 'anl');
      var section = document.createElement('section');
      section.setAttribute('data-hook', 'consent-banner-section-root');
      section.style.cssText = 'display:grid;grid-template-columns:1fr auto;column-gap:16px;margin:10px 0';
      section.innerHTML =
        '<h3 data-hook="consent-banner-section-title" style="margin:0;font-size:15px">' + CATEGORIES[i][1] + '</h3>' +
        '<p data-hook="consent-banner-section-description" style="grid-column:1;margin:2px 0 0">' + CATEGORIES[i][2] + '</p>' +
        '<span data-hook="consent-banner-section-toggle" style="position:relative;grid-column:2;grid-row:1 / span 2;display:inline-block;width:40px;height:22px;border-radius:11px;cursor:pointer">' +
        '<input type="checkbox" data-hook="consent-banner-section-toggle-input" style="' + HIDDEN_INPUT + '"></span>';
      var input = section.querySelector('input');
      input.checked = lockedOn || (key === 'anl' && analyticsOn);
      input.disabled = lockedOn;
      toggleOf(section.querySelector('span'), input);
      inputs[key] = input;
      dialog.appendChild(section);
    }

    if (settingsVariant === 'two-saves') dialog.appendChild(saveButton('Auswahl speichern', '#fff', '#116dff'));
    dialog.appendChild(saveButton('Auswahl bestätigen', '#116dff', '#fff'));
    el.appendChild(dialog);
    return { el: el, inputs: inputs, panel: dialog };
  }

  // The shown toggle paints the state of the hidden checkbox and switches it on a click.
  function toggleOf(toggle, input) {
    function paint() { toggle.style.background = input.checked ? '#116dff' : '#bbb'; }
    paint();
    toggle.addEventListener('click', function () {
      if (input.disabled) return;
      input.checked = !input.checked;
      paint();
    });
  }

  function saveButton(label, background, color) {
    var b = document.createElement('button');
    b.setAttribute('data-hook', 'consent-banner-settings-save-button');
    b.style.cssText = btn + 'display:block;margin:12px 0 0 auto;background:' + background + ';color:' + color;
    b.textContent = label;
    return b;
  }

  var CLOSE_ICON = 'data:image/svg+xml,' + encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24"><path d="M6 6l12 12M18 6L6 18" stroke="#000" stroke-width="2"/></svg>');
  function render() {
    var decline = variant === 'decline';
    var root = document.createElement('div');
    root.className = 'consent-banner-root';
    root.setAttribute('data-hook', 'consent-banner-root');
    root.setAttribute('aria-labelledby', 'cookies_policy_description');
    root.setAttribute('role', 'region');
    root.setAttribute('data-comp-type', 'cookie-banner-root-uou');
    root.setAttribute('tabindex', '-1');
    root.style.cssText = 'position:fixed;left:0;right:0;bottom:0;z-index:99999;display:flex;align-items:center;background:#fff;color:#222;box-shadow:0 -2px 8px rgba(0,0,0,.2);padding:8px 48px 8px 24px;font:14px/1.4 sans-serif';
    root.innerHTML =
      '<div class="consent-banner-root-container" style="display:flex;align-items:center;width:100%">' +
      '<div style="flex:1"><span class="consent-banner-description" id="cookies_policy_description" data-hook="consent-banner-description" aria-hidden="true">' +
      'Diese Seite setzt Cookies ein, um ihre Nutzung auszuwerten. Mit „Zustimmen“ erlauben Sie das. ' +
      '<a data-hook="consent-banner-view-policy-link" href="/datenschutz" target="_self">' + (decline ? 'Datenschutzerklärung' : 'Zur Datenschutzerklärung') + '</a></span></div>' +
      '<div class="consent-banner-buttons">' +
      (decline
        ? '<span data-hook="consent-banner-settings-button" role="button" tabindex="0" style="' + btn + 'display:inline-block;border:0;text-decoration:underline">Einstellungen</span>' +
          '<button data-hook="consent-banner-decline-all-button" style="' + btn + 'background:#fff;color:#116dff">Alle ablehnen</button>'
        : variant === 'close-only' || variant === 'settings-outside'
          ? ''
          : '<button data-hook="consent-banner-settings-button" style="' + btn + 'background:#fff;color:#116dff">Cookie-Einstellungen</button>') +
      '<button data-hook="consent-banner-apply-button" style="' + btn + 'background:#116dff;color:#fff">Zustimmen</button>' +
      '</div></div>' +
      '<span class="consent-banner-close-button-container" style="position:absolute;right:8px;top:8px">' +
      '<button data-hook="consent-banner-close-button" aria-label="Schließen" style="border:0;background:none;padding:4px;cursor:pointer">' +
      '<img alt="Schließen" width="24" height="24" src="' + CLOSE_ICON + '"></button></span>';
    document.body.appendChild(root);

    function done(all) { save(all); root.remove(); }
    root.querySelector('[data-hook="consent-banner-apply-button"]').addEventListener('click', function () { done(true); });
    var declineBtn = root.querySelector('[data-hook="consent-banner-decline-all-button"]');
    if (declineBtn) declineBtn.addEventListener('click', function () { done(false); });
    root.querySelector('[data-hook="consent-banner-close-button"]').addEventListener('click', function () { root.remove(); });

    var opener = root.querySelector('[data-hook="consent-banner-settings-button"]');
    if (variant === 'settings-outside') {
      // A settings control of the page itself, outside the banner, with the vendor's hook.
      opener = document.createElement('button');
      opener.setAttribute('data-hook', 'consent-banner-settings-button');
      opener.textContent = 'Cookie-Einstellungen';
      opener.style.cssText = 'position:fixed;left:24px;top:24px;z-index:99998;' + btn;
      document.body.appendChild(opener);
    }
    if (opener) opener.addEventListener('click', function () { openSettings(root); });
  }

  if (stored && stored.anl === 1) loadTracker();
  if (!stored) {
    if (document.body) render();
    else document.addEventListener('DOMContentLoaded', render);
  }
})();
